#!/usr/bin/env bash
# Collect the license text of every third-party crate in Cargo.lock into
# licenses/LICENSE-<crate> (no version in the name; when Cargo.lock pins several
# versions of the same crate, their texts are merged into the one file).
#
# Usage:
#   scripts/licenses.sh            # copy/refresh license files
#   scripts/licenses.sh --check    # report missing/empty license files, exit 1 if any
#   scripts/licenses.sh --clean    # remove generated files, keep hand-written ones
#   scripts/licenses.sh --list     # print the crates that would be collected

set -euo pipefail

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
CARGO_LOCK="$ROOT/Cargo.lock"
OUT_DIR="$ROOT/licenses"
# Every generated file starts with this line, which is how the script tells its
# own output apart from hand-written SPDX texts (LICENSE-MIT, LICENSE-GPL-3.0, ...).
MARKER='# Generated by scripts/licenses.sh'

MODE=sync
QUIET=0

usage() {
	sed -n '2,12p' "${BASH_SOURCE[0]}" | sed 's/^# \{0,1\}//'
	exit "${1:-0}"
}

while [ $# -gt 0 ]; do
	case "$1" in
	--check) MODE=check ;;
	--clean) MODE=clean ;;
	--list) MODE=list ;;
	-q | --quiet) QUIET=1 ;;
	-h | --help) usage 0 ;;
	*) echo "unknown option: $1" >&2; usage 1 ;;
	esac
	shift
done

log() { [ "$QUIET" = 1 ] || printf '%s\n' "$*"; }
die() { printf 'error: %s\n' "$*" >&2; exit 1; }

registry_src() {
	local base="${CARGO_HOME:-$HOME/.cargo}/registry/src"
	[ -d "$base" ] || return 1
	find "$base" -mindepth 1 -maxdepth 1 -type d 2>/dev/null | sort | tail -n 1
}

# name<TAB>version pairs from Cargo.lock, excluding path/workspace members.
locked_crates() {
	awk '
		/^\[\[package\]\]/ { name=""; version=""; source="" }
		/^name = / { if (name == "") { name=$0; sub(/^name = "/, "", name); sub(/"$/, "", name) } }
		/^version = / { if (version == "") { version=$0; sub(/^version = "/, "", version); sub(/"$/, "", version) } }
		/^source = / { source=$0 }
		/^$/ {
			if (name != "" && source ~ /registry/) print name "\t" version
			name=""; version=""; source=""
		}
		END { if (name != "" && source ~ /registry/) print name "\t" version }
	' "$CARGO_LOCK" | sort -u
}

SRC_ROOT="$(registry_src || true)"

is_generated() {
	[ -f "$1" ] || return 1
	[ "$(head -n 1 -- "$1" 2>/dev/null)" = "$MARKER" ]
}

# NUL-separated paths of the generated license files.
list_generated() {
	local f
	[ -d "$OUT_DIR" ] || return 0
	for f in "$OUT_DIR"/LICENSE-*; do
		[ -f "$f" ] || continue
		is_generated "$f" && printf '%s\0' "$f"
	done
	return 0
}

# License body for one crate version on stdout: the upstream LICENSE/COPYING/NOTICE
# files joined by "=====" banners. Returns 1 when nothing at all could be found.
crate_body() {
	local name="$1" version="$2" src="$SRC_ROOT/$1-$2"
	local f spdx license_file
	local -a files=()

	if [ -z "$SRC_ROOT" ] || [ ! -d "$src" ]; then
		log "warn: no vendored source for $name-$version (run 'cargo fetch' first)"
		return 1
	fi

	# A crate may ship LICENSE, LICENSE-MIT, LICENSE-APACHE, COPYING, ...
	mapfile -d '' files < <(
		find "$src" -maxdepth 1 -type f \
			\( -iname 'license*' -o -iname 'copying*' -o -iname 'notice*' \) -print0 | sort -z
	)

	if [ "${#files[@]}" -eq 0 ]; then
		# Some crates declare an SPDX id in Cargo.toml but ship no license text.
		spdx="$(sed -n 's/^license *= *"\(.*\)" *$/\1/p' "$src/Cargo.toml" | head -n 1)"
		license_file="$(sed -n 's/^license-file *= *"\(.*\)" *$/\1/p' "$src/Cargo.toml" | head -n 1)"
		if [ -n "$license_file" ] && [ -f "$src/$license_file" ]; then
			files=("$src/$license_file")
		else
			printf '# Upstream ships no license file; declared license: %s\n' "${spdx:-unknown}"
			printf '# Upstream: https://crates.io/crates/%s/%s\n' "$name" "$version"
			return 0
		fi
	fi

	for f in "${files[@]}"; do
		printf '\n===== %s =====\n\n' "${f##*/}"
		cat "$f"
	done
}

if [ "$MODE" = list ]; then
	locked_crates | cut -f1 | uniq
	exit 0
fi

if [ "$MODE" = clean ]; then
	removed=0
	[ -d "$OUT_DIR" ] || exit 0
	while IFS= read -r -d '' f; do
		rm -f "$f"
		removed=$((removed + 1))
	done < <(list_generated)
	log "removed $removed generated license file(s) from ${OUT_DIR#"$ROOT"/}"
	exit 0
fi

[ -f "$CARGO_LOCK" ] || die "$CARGO_LOCK not found"

mkdir -p "$OUT_DIR"
chmod 0755 "$OUT_DIR"

# Remove stale generated files (a crate dropped from the lock, or one now
# hand-maintained) so they do not linger. Only in sync mode: --check and --list
# must not modify the tree.
if [ "$MODE" = sync ]; then
	while IFS= read -r -d '' f; do
		rm -f "$f"
	done < <(list_generated)
fi

total=0
written=0
missing=()

work="$(mktemp -d)"
trap 'rm -rf "$work"' EXIT

while IFS=$'\t' read -r name versions; do
	total=$((total + 1))
	dest="$OUT_DIR/LICENSE-$name"

	if [ "$MODE" = check ]; then
		[ -s "$dest" ] || missing+=("$name")
		continue
	fi

	# Refuse to clobber a hand-written SPDX text that happens to share the name.
	if [ -e "$dest" ] && ! is_generated "$dest"; then
		log "warn: $dest exists and was not generated by this script; skipping"
		missing+=("$name")
		continue
	fi

	# One body per pinned version, so a crate with several versions in the lock
	# only repeats the text when the texts actually differ.
	rm -f "$work"/body.* "$work"/hash.*
	vs=()
	for version in $versions; do
		vs+=("$version")
	done
	i=0
	unique=0
	for version in "${vs[@]}"; do
		i=$((i + 1))
		if crate_body "$name" "$version" >"$work/body.$i" && [ -s "$work/body.$i" ]; then
			cksum <"$work/body.$i" | { read -r sum _; echo "$sum"; } >"$work/hash.$i"
			seen=0
			for j in $(seq 1 $((i - 1))); do
				if [ -f "$work/hash.$j" ] && cmp -s "$work/body.$i" "$work/body.$j"; then
					seen=1
					break
				fi
			done
			[ "$seen" = 1 ] || unique=$((unique + 1))
		else
			log "warn: no license text for $name-$version"
			missing+=("$name-$version")
		fi
	done

	tmp="$(mktemp "$OUT_DIR/.LICENSE-$name.XXXXXX")"
	{
		printf '%s\n' "$MARKER"
		printf '# Crate: %s (crates.io)\n' "$name"
		printf '# Versions in Cargo.lock: %s\n' "$(printf '%s ' "${vs[@]}")"
		if [ "$unique" -le 1 ]; then
			cat "$work/body.1" 2>/dev/null || true
		else
			# Texts differ between versions: keep one labelled section per version.
			i=0
			for version in "${vs[@]}"; do
				i=$((i + 1))
				[ -s "$work/body.$i" ] || continue
				printf '\n########## %s %s ##########\n' "$name" "$version"
				cat "$work/body.$i"
			done
		fi
	} >"$tmp"
	chmod 0644 "$tmp"
	mv -f "$tmp" "$dest"
	written=$((written + 1))
done < <(locked_crates | awk -F'\t' '{ v[$1] = v[$1] (v[$1] == "" ? "" : " ") $2 } END { for (n in v) print n "\t" v[n] }' | sort)

if [ "$MODE" = check ]; then
	if [ "${#missing[@]}" -gt 0 ]; then
		echo "missing or empty license files (${#missing[@]}/$total):" >&2
		printf '  %s\n' "${missing[@]}" >&2
		exit 1
	fi
	log "all $total crate license files present in ${OUT_DIR#"$ROOT"/}"
	exit 0
fi

log "crates in Cargo.lock: $total"
log "license files written: $written"
if [ "${#missing[@]}" -gt 0 ]; then
	echo "no license text collected for ${#missing[@]} crate(s):" >&2
	printf '  %s\n' "${missing[@]}" >&2
	exit 1
fi
